for i,(channel,cs,socket) in enumerate([('BaseColor','sRGB','Base Color'),('Roughness','Non-Color','Roughness'),('Metallic','Non-Color','Metallic'),('NormalGL','Non-Color',None)]):
 im=bpy.data.images.load(str(T/f'{prefix}_{channel}_{suffix}.png'),check_existing=True);im.colorspace_settings.name=cs
 tex=nd.new('ShaderNodeTexImage');tex.image=im;tex.name=channel;tex.label=channel+' / '+cs;tex.location=(-450,350-i*220);tex.interpolation='Linear';tex.extension='EXTEND' if prefix.startswith('DoorLeaf') else 'REPEAT'
 if socket:lk.new(tex.outputs['Color'],p.inputs[socket])
 else:
  n=nd.new('ShaderNodeNormalMap');n.location=(0,-220);n.inputs['Strength'].default_value=1;n.space='TANGENT';lk.new(tex.outputs['Color'],n.inputs['Color']);lk.new(n.outputs['Normal'],p.inputs['Normal'])

if o.name in ['LEAF_L_Panel_2mm','LEAF_R_Panel_2mm']:
 uv=o.data.uv_layers.active
 for item in uv.data:
  u,v=item.uv;local_u=(u-.02)/.46 if u<.5 else (u-.52)/.46
  item.uv=(.3125+local_u*(1840/4096),(v-.02)/.96)
